INSERT INTO `hr_contract` VALUES
(8,'NCE/K1/001/2026',18,1,NULL,'K1','ACTIVE','COOK','KITCHEN',1400000.00,200000.00,0.00,0.00,5982.91,'2026-03-01','2026-06-01','e46fde23531fcaf1ef7f44c7ee3fc921','72cb7b68136969d13eaa01cf7c15fb40aba009d7500997f24b597c13dfad4d33','2026-04-03 16:48:12','<div style=\"text-align:center;margin-bottom:20px;padding-bottom:14px;border-bottom:2px solid #222\"><img src=\"https://core.namuacoffee.com/assets/img/logo.png\" alt=\"Namua Coffee\" style=\"height:68px;display:block;margin:0 auto 10px\"><div style=\"font-family:Arial,sans-serif;font-size:16px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase\">Namua Coffee and Eatery</div><div style=\"font-family:Arial,sans-serif;font-size:13px;color:#555;margin-top:3px\">Jl. Magnolia, Kabongan Kidul, Kecamatan Rembang</div><div style=\"font-family:Arial,sans-serif;margin-top:12px;font-size:19px;font-weight:bold;text-transform:uppercase;letter-spacing:.6px\">Perjanjian Kerja Waktu Tertentu</div><div style=\"font-family:Arial,sans-serif;font-size:17px;font-weight:bold;margin-top:2px\">Kontrak 1 &mdash; Masa Training (3 bulan)</div></div><div style=\"font-family:\'Times New Roman\',Times,Georgia,serif;font-size:16px;line-height:1.85;color:#1a1a1a\"><p style=\"margin:0 0 8px;text-align:justify;line-height:1.85\">Pada hari ini, 3 April 2026, telah disepakati dan ditandatangani Perjanjian Kerja Waktu Tertentu (PKWT) oleh dan antara:</p><table style=\"width:100%;margin-bottom:14px;border-collapse:collapse;font-family:\'Times New Roman\',Times,Georgia,serif;font-size:16px\"><tr><td style=\"width:28%;padding:5px 10px;border:1px solid #ccc;background:#f5f5f5;font-weight:bold;vertical-align:top\">Pihak Pertama</td><td style=\"padding:5px 10px;border:1px solid #ccc;vertical-align:top\">: <strong>Namua Coffee and Eatery</strong>, diwakili oleh <strong>Anis Fitriya</strong> selaku Owner, berkedudukan di Jl. Magnolia, Desa Kabongan Kidul, Kecamatan Rembang. Selanjutnya disebut <strong>PERUSAHAAN</strong>.</td></tr><tr><td style=\"padding:5px 10px;border:1px solid #ccc;background:#f5f5f5;font-weight:bold;vertical-align:top\">Pihak Kedua</td><td style=\"padding:5px 10px;border:1px solid #ccc;vertical-align:top\">: <strong>AHMAD SETIAWAN</strong>, dengan jabatan <strong>COOK</strong> pada divisi <strong>KITCHEN</strong>. Selanjutnya disebut <strong>PEGAWAI</strong>.</td></tr></table><p style=\"margin:0 0 8px;text-align:justify;line-height:1.85\">Para pihak sepakat untuk membuat perjanjian kerja dengan ketentuan sebagai berikut:</p><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 1<br>Status dan Masa Kerja</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">PEGAWAI diterima sebagai <strong>Pegawai Kontrak 1 (Masa Training)</strong> untuk jabatan <strong>COOK</strong> di divisi <strong>KITCHEN</strong>, ditempatkan di Namua Coffee and Eatery, Rembang.</li><li style=\"margin-bottom:5px\">Masa kerja selama <strong>3 bulan</strong>, terhitung sejak <strong>1 Maret 2026</strong> hingga <strong>1 Juni 2026</strong>.</li><li style=\"margin-bottom:5px\">Masa training merupakan periode uji kelayakan. Selama masa ini, PERUSAHAAN berhak mengakhiri perjanjian kerja sewaktu-waktu dengan memberikan pemberitahuan tertulis kepada PEGAWAI.</li><li style=\"margin-bottom:5px\">Pada akhir masa kontrak, PERUSAHAAN melakukan evaluasi kinerja. Hasil evaluasi menentukan kelanjutan hubungan kerja ke Kontrak 2.</li><li style=\"margin-bottom:5px\">Tidak ada kewajiban dari PERUSAHAAN untuk melanjutkan hubungan kerja setelah masa kontrak berakhir.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 2<br>Jam dan Hari Kerja</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Hari kerja: <strong>26 (dua puluh enam) hari</strong> dalam setiap bulan kalender.</li><li style=\"margin-bottom:5px\">Jam kerja: <strong>9 (sembilan) jam per hari</strong>, termasuk 1 (satu) jam istirahat.</li><li style=\"margin-bottom:5px\">Sistem kerja: <strong>shift</strong> sesuai jadwal yang ditetapkan oleh Supervisor atau Head of Division (HOD).</li><li style=\"margin-bottom:5px\">PEGAWAI wajib hadir tepat waktu. Keterlambatan diperhitungkan sebagai pengurangan kompensasi harian sesuai kebijakan perusahaan.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 3<br>Kompensasi</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Kompensasi PEGAWAI terdiri atas:\n      <table style=\"width:100%;margin:6px 0 0;border-collapse:collapse;font-family:inherit;font-size:16px\">\n        <tr>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;width:38%;background:#f5f5f5\">Gaji Pokok Dasar</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc\">: <strong>Rp 1.200.000</strong> / bulan</td>\n        </tr>\n        <tr>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;background:#f5f5f5\">Tunjangan Jabatan</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc\">: <strong>Rp 200.000</strong> / bulan</td>\n        </tr>\n        <tr>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;background:#f5f5f5\">Tunjangan Objektif</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc\">: <strong>Rp 0</strong> / bulan</td>\n        </tr>\n        <tr style=\"background:#e8f0fe\">\n          <td style=\"padding:3px 8px;border:1px solid #ccc;font-weight:bold\">Total Kompensasi Tetap</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;font-weight:bold\">: <strong>Rp 1.400.000</strong> / bulan</td>\n        </tr>\n      </table></li><li style=\"margin-bottom:5px\">Kompensasi tetap dibayarkan setiap tanggal 1&ndash;3 bulan berikutnya melalui transfer ke rekening bank PEGAWAI.</li><li style=\"margin-bottom:5px\">Tunjangan Hari Raya (THR): diberikan secara proporsional berdasarkan masa kerja aktual pada kontrak ini.</li><li style=\"margin-bottom:5px\">Review kompensasi dari Kontrak 1 ke Kontrak 2 dilakukan berdasarkan hasil evaluasi &mdash; tidak berlaku otomatis.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 4<br>Lembur</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Lembur dilaksanakan atas permintaan dan persetujuan tertulis Supervisor/HOD.</li><li style=\"margin-bottom:5px\">Tarif lembur: <strong>Rp 8.000</strong> per jam.</li><li style=\"margin-bottom:5px\">Lembur pada hari libur nasional yang tidak dijadwalkan sebelumnya: tarif sebesar <strong>1,5&times;</strong> tarif lembur normal.</li><li style=\"margin-bottom:5px\">Pembayaran lembur disatukan dengan kompensasi bulanan.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 5<br>Ketidakhadiran dan Cuti Di Luar Tanggungan</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Sistem kompensasi PEGAWAI bersifat <strong>harian</strong>. Kompensasi dihitung berdasarkan hari kerja aktual dalam setiap bulan.</li><li style=\"margin-bottom:5px\">Ketidakhadiran tanpa keterangan diperhitungkan sebagai hari tidak masuk dan kompensasi tidak dibayarkan untuk hari tersebut.</li><li style=\"margin-bottom:5px\"><strong>Cuti Di Luar Tanggungan Perusahaan (CLTP):</strong> PEGAWAI dapat mengajukan izin tidak masuk kepada Supervisor/HOD. Izin yang disetujui dicatat sebagai CLTP; kompensasi untuk hari tersebut tidak dibayarkan.</li><li style=\"margin-bottom:5px\">Izin mendadak wajib dilaporkan sebelum jam mulai shift. Ketidakhadiran tanpa pemberitahuan selama 3 (tiga) hari kerja berturut-turut dianggap sebagai pengunduran diri sepihak.</li><li style=\"margin-bottom:5px\">Cuti Sakit: sakit lebih dari 2 (dua) hari berturut-turut wajib disertai surat keterangan dokter. Hari sakit diperhitungkan sebagai hari tidak masuk.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 6<br>Kewajiban Pegawai</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Melaksanakan tugas sesuai jabatan dan instruksi atasan dengan penuh tanggung jawab dan integritas.</li><li style=\"margin-bottom:5px\">Mematuhi seluruh peraturan, SOP, dan standar pelayanan perusahaan.</li><li style=\"margin-bottom:5px\">Menjaga kebersihan, kerapian, dan keselamatan di area kerja.</li><li style=\"margin-bottom:5px\">Berpenampilan rapi sesuai standar perusahaan selama jam kerja.</li><li style=\"margin-bottom:5px\">Menjaga kerahasiaan resep, data pelanggan, dan informasi bisnis perusahaan selama masa kerja dan 6 bulan setelahnya.</li><li style=\"margin-bottom:5px\">Tidak merangkap pekerjaan di tempat lain tanpa izin tertulis perusahaan.</li><li style=\"margin-bottom:5px\">Melaporkan kepada atasan setiap kejadian atau kondisi yang berpotensi merugikan perusahaan.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 7<br>Hak Pegawai</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Menerima kompensasi tetap tepat waktu sesuai kesepakatan.</li><li style=\"margin-bottom:5px\">Mendapatkan slip kompensasi setiap bulan.</li><li style=\"margin-bottom:5px\">Mendapatkan lingkungan kerja yang aman, layak, dan bebas dari diskriminasi.</li><li style=\"margin-bottom:5px\">Mendapatkan pelatihan dasar yang diperlukan untuk pelaksanaan tugas.</li><li style=\"margin-bottom:5px\">Mendapatkan pemberitahuan dan hasil evaluasi sebelum berakhirnya masa kontrak.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 8<br>Larangan dan Sanksi</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">PEGAWAI dilarang: mencuri, menipu, memalsukan data, mengonsumsi alkohol/narkoba di tempat kerja, melakukan pelecehan atau kekerasan, dan membocorkan rahasia perusahaan.</li><li style=\"margin-bottom:5px\">Pelanggaran ringan (terlambat berulang, tidak mengikuti SOP): teguran lisan &rarr; teguran tertulis &rarr; Surat Peringatan (SP).</li><li style=\"margin-bottom:5px\">Pelanggaran berat (butir 1): Pemutusan Hubungan Kerja (PHK) seketika tanpa kompensasi.</li><li style=\"margin-bottom:5px\">3 (tiga) SP aktif dalam 1 (satu) periode kontrak menjadi dasar pengakhiran kontrak.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 9<br>Pengunduran Diri</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">PEGAWAI yang mengundurkan diri wajib memberitahu secara tertulis minimum <strong>30 (tiga puluh) hari</strong> sebelum tanggal efektif.</li><li style=\"margin-bottom:5px\">Pengunduran diri sebelum masa kontrak berakhir tanpa alasan yang dapat diterima dikenakan denda sebesar <strong>Rp 500.000,-</strong>.</li><li style=\"margin-bottom:5px\">PEGAWAI tetap melaksanakan tugas dan kewajibannya penuh hingga batas waktu pengunduran diri berlaku.</li><li style=\"margin-bottom:5px\">PEGAWAI wajib menyelesaikan serah terima tugas dan mengembalikan seluruh inventaris perusahaan dalam kondisi baik.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 10<br>Force Majeure</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Dalam kondisi darurat (bencana alam, pandemi, kebijakan pemerintah) yang menyebabkan operasional terganggu, para pihak bermusyawarah dalam 14 (empat belas) hari untuk mencari solusi bersama.</li><li style=\"margin-bottom:5px\">Pemotongan kompensasi akibat force majeure tidak melebihi <strong>25%</strong> dari kompensasi tetap dan harus atas kesepakatan bersama.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 11<br>Pengakhiran Kontrak</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Kontrak berakhir sendirinya pada tanggal <strong>1 Juni 2026</strong>.</li><li style=\"margin-bottom:5px\">PERUSAHAAN dapat mengakhiri kontrak sebelum waktunya apabila PEGAWAI melakukan pelanggaran berat atau tidak memenuhi standar kinerja minimum setelah evaluasi dan peringatan tertulis.</li><li style=\"margin-bottom:5px\">Berakhirnya PKWT secara alami tidak menimbulkan kewajiban pesangon sesuai PP No. 35 Tahun 2021.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 12<br>Ketentuan Lain</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Peraturan Perusahaan dan SOP yang berlaku merupakan satu kesatuan yang tidak terpisahkan dari perjanjian ini.</li><li style=\"margin-bottom:5px\">Perubahan isi perjanjian hanya sah apabila dibuat secara tertulis dan ditandatangani oleh kedua belah pihak.</li><li style=\"margin-bottom:5px\">Hal-hal yang belum diatur dalam perjanjian ini akan diatur kemudian atas kesepakatan para pihak dalam suatu amandemen.</li><li style=\"margin-bottom:5px\">Perjanjian ini tunduk pada hukum yang berlaku di Indonesia, khususnya UU No. 11 Tahun 2020 tentang Cipta Kerja jo. PP No. 35 Tahun 2021.</li><li style=\"margin-bottom:5px\">Perselisihan diselesaikan secara musyawarah. Apabila tidak tercapai, diselesaikan melalui mekanisme ketenagakerjaan yang berlaku.</li></ol></div></div>','',67,'2026-04-03 16:48:12',67,'2026-04-03 16:48:12','2026-08-29 16:29:18'),
(9,'NCE/K1/002/2026',52,1,NULL,'K1','ACTIVE','BARISTA','BAR',1200000.00,0.00,0.00,0.00,8000.00,'2026-03-28','2026-06-28','79bfa1389ae123510b028c27c0c33776','834f8c646a0d5896e71584373cabbdfc8a8494c53eb8ccc4a52cade1dfb75b8a','2026-04-03 17:01:21','<div style=\"text-align:center;margin-bottom:20px;padding-bottom:14px;border-bottom:2px solid #222\"><img src=\"https://core.namuacoffee.com/assets/img/logo.png\" alt=\"Namua Coffee\" style=\"height:68px;display:block;margin:0 auto 10px\"><div style=\"font-family:Arial,sans-serif;font-size:16px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase\">Namua Coffee and Eatery</div><div style=\"font-family:Arial,sans-serif;font-size:13px;color:#555;margin-top:3px\">Jl. Magnolia, Kabongan Kidul, Kecamatan Rembang</div><div style=\"font-family:Arial,sans-serif;margin-top:12px;font-size:19px;font-weight:bold;text-transform:uppercase;letter-spacing:.6px\">Perjanjian Kerja Waktu Tertentu</div><div style=\"font-family:Arial,sans-serif;font-size:17px;font-weight:bold;margin-top:2px\">Kontrak 1 &mdash; Masa Training (3 bulan)</div></div><div style=\"font-family:\'Times New Roman\',Times,Georgia,serif;font-size:16px;line-height:1.85;color:#1a1a1a\"><p style=\"margin:0 0 8px;text-align:justify;line-height:1.85\">Pada hari ini, 3 April 2026, telah disepakati dan ditandatangani Perjanjian Kerja Waktu Tertentu (PKWT) oleh dan antara:</p><table style=\"width:100%;margin-bottom:14px;border-collapse:collapse;font-family:\'Times New Roman\',Times,Georgia,serif;font-size:16px\"><tr><td style=\"width:28%;padding:5px 10px;border:1px solid #ccc;background:#f5f5f5;font-weight:bold;vertical-align:top\">Pihak Pertama</td><td style=\"padding:5px 10px;border:1px solid #ccc;vertical-align:top\">: <strong>Namua Coffee and Eatery</strong>, diwakili oleh <strong>Anis Fitriya</strong> selaku Owner, berkedudukan di Jl. Magnolia, Desa Kabongan Kidul, Kecamatan Rembang. Selanjutnya disebut <strong>PERUSAHAAN</strong>.</td></tr><tr><td style=\"padding:5px 10px;border:1px solid #ccc;background:#f5f5f5;font-weight:bold;vertical-align:top\">Pihak Kedua</td><td style=\"padding:5px 10px;border:1px solid #ccc;vertical-align:top\">: <strong>NAYLA SYAHFIQAH</strong>, dengan jabatan <strong>BARISTA</strong> pada divisi <strong>BAR</strong>. Selanjutnya disebut <strong>PEGAWAI</strong>.</td></tr></table><p style=\"margin:0 0 8px;text-align:justify;line-height:1.85\">Para pihak sepakat untuk membuat perjanjian kerja dengan ketentuan sebagai berikut:</p><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 1<br>Status dan Masa Kerja</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">PEGAWAI diterima sebagai <strong>Pegawai Kontrak 1 (Masa Training)</strong> untuk jabatan <strong>BARISTA</strong> di divisi <strong>BAR</strong>, ditempatkan di Namua Coffee and Eatery, Rembang.</li><li style=\"margin-bottom:5px\">Masa kerja selama <strong>3 bulan</strong>, terhitung sejak <strong>28 Maret 2026</strong> hingga <strong>28 Juni 2026</strong>.</li><li style=\"margin-bottom:5px\">Masa training merupakan periode uji kelayakan. Selama masa ini, PERUSAHAAN berhak mengakhiri perjanjian kerja sewaktu-waktu dengan memberikan pemberitahuan tertulis kepada PEGAWAI.</li><li style=\"margin-bottom:5px\">Pada akhir masa kontrak, PERUSAHAAN melakukan evaluasi kinerja. Hasil evaluasi menentukan kelanjutan hubungan kerja ke Kontrak 2.</li><li style=\"margin-bottom:5px\">Tidak ada kewajiban dari PERUSAHAAN untuk melanjutkan hubungan kerja setelah masa kontrak berakhir.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 2<br>Jam dan Hari Kerja</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Hari kerja: <strong>26 (dua puluh enam) hari</strong> dalam setiap bulan kalender.</li><li style=\"margin-bottom:5px\">Jam kerja: <strong>9 (sembilan) jam per hari</strong>, termasuk 1 (satu) jam istirahat.</li><li style=\"margin-bottom:5px\">Sistem kerja: <strong>shift</strong> sesuai jadwal yang ditetapkan oleh Supervisor atau Head of Division (HOD).</li><li style=\"margin-bottom:5px\">PEGAWAI wajib hadir tepat waktu. Keterlambatan diperhitungkan sebagai pengurangan kompensasi harian sesuai kebijakan perusahaan.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 3<br>Kompensasi</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Kompensasi PEGAWAI terdiri atas:\n      <table style=\"width:100%;margin:6px 0 0;border-collapse:collapse;font-family:inherit;font-size:16px\">\n        <tr>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;width:38%;background:#f5f5f5\">Gaji Pokok Dasar</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc\">: <strong>Rp 1.200.000</strong> / bulan</td>\n        </tr>\n        <tr>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;background:#f5f5f5\">Tunjangan Jabatan</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc\">: <strong>Rp 0</strong> / bulan</td>\n        </tr>\n        <tr>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;background:#f5f5f5\">Tunjangan Objektif</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc\">: <strong>Rp 0</strong> / bulan</td>\n        </tr>\n        <tr style=\"background:#e8f0fe\">\n          <td style=\"padding:3px 8px;border:1px solid #ccc;font-weight:bold\">Total Kompensasi Tetap</td>\n          <td style=\"padding:3px 8px;border:1px solid #ccc;font-weight:bold\">: <strong>Rp 1.200.000</strong> / bulan</td>\n        </tr>\n      </table></li><li style=\"margin-bottom:5px\">Kompensasi tetap dibayarkan setiap tanggal 1&ndash;3 bulan berikutnya melalui transfer ke rekening bank PEGAWAI.</li><li style=\"margin-bottom:5px\">Tunjangan Hari Raya (THR): diberikan secara proporsional berdasarkan masa kerja aktual pada kontrak ini.</li><li style=\"margin-bottom:5px\">Review kompensasi dari Kontrak 1 ke Kontrak 2 dilakukan berdasarkan hasil evaluasi &mdash; tidak berlaku otomatis.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 4<br>Lembur</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Lembur dilaksanakan atas permintaan dan persetujuan tertulis Supervisor/HOD.</li><li style=\"margin-bottom:5px\">Tarif lembur: <strong>Rp 8.000</strong> per jam.</li><li style=\"margin-bottom:5px\">Lembur pada hari libur nasional yang tidak dijadwalkan sebelumnya: tarif sebesar <strong>1,5&times;</strong> tarif lembur normal.</li><li style=\"margin-bottom:5px\">Pembayaran lembur disatukan dengan kompensasi bulanan.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 5<br>Ketidakhadiran dan Cuti Di Luar Tanggungan</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Sistem kompensasi PEGAWAI bersifat <strong>harian</strong>. Kompensasi dihitung berdasarkan hari kerja aktual dalam setiap bulan.</li><li style=\"margin-bottom:5px\">Ketidakhadiran tanpa keterangan diperhitungkan sebagai hari tidak masuk dan kompensasi tidak dibayarkan untuk hari tersebut.</li><li style=\"margin-bottom:5px\"><strong>Cuti Di Luar Tanggungan Perusahaan (CLTP):</strong> PEGAWAI dapat mengajukan izin tidak masuk kepada Supervisor/HOD. Izin yang disetujui dicatat sebagai CLTP; kompensasi untuk hari tersebut tidak dibayarkan.</li><li style=\"margin-bottom:5px\">Izin mendadak wajib dilaporkan sebelum jam mulai shift. Ketidakhadiran tanpa pemberitahuan selama 3 (tiga) hari kerja berturut-turut dianggap sebagai pengunduran diri sepihak.</li><li style=\"margin-bottom:5px\">Cuti Sakit: sakit lebih dari 2 (dua) hari berturut-turut wajib disertai surat keterangan dokter. Hari sakit diperhitungkan sebagai hari tidak masuk.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 6<br>Kewajiban Pegawai</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Melaksanakan tugas sesuai jabatan dan instruksi atasan dengan penuh tanggung jawab dan integritas.</li><li style=\"margin-bottom:5px\">Mematuhi seluruh peraturan, SOP, dan standar pelayanan perusahaan.</li><li style=\"margin-bottom:5px\">Menjaga kebersihan, kerapian, dan keselamatan di area kerja.</li><li style=\"margin-bottom:5px\">Berpenampilan rapi sesuai standar perusahaan selama jam kerja.</li><li style=\"margin-bottom:5px\">Menjaga kerahasiaan resep, data pelanggan, dan informasi bisnis perusahaan selama masa kerja dan 6 bulan setelahnya.</li><li style=\"margin-bottom:5px\">Tidak merangkap pekerjaan di tempat lain tanpa izin tertulis perusahaan.</li><li style=\"margin-bottom:5px\">Melaporkan kepada atasan setiap kejadian atau kondisi yang berpotensi merugikan perusahaan.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 7<br>Hak Pegawai</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Menerima kompensasi tetap tepat waktu sesuai kesepakatan.</li><li style=\"margin-bottom:5px\">Mendapatkan slip kompensasi setiap bulan.</li><li style=\"margin-bottom:5px\">Mendapatkan lingkungan kerja yang aman, layak, dan bebas dari diskriminasi.</li><li style=\"margin-bottom:5px\">Mendapatkan pelatihan dasar yang diperlukan untuk pelaksanaan tugas.</li><li style=\"margin-bottom:5px\">Mendapatkan pemberitahuan dan hasil evaluasi sebelum berakhirnya masa kontrak.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 8<br>Larangan dan Sanksi</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">PEGAWAI dilarang: mencuri, menipu, memalsukan data, mengonsumsi alkohol/narkoba di tempat kerja, melakukan pelecehan atau kekerasan, dan membocorkan rahasia perusahaan.</li><li style=\"margin-bottom:5px\">Pelanggaran ringan (terlambat berulang, tidak mengikuti SOP): teguran lisan &rarr; teguran tertulis &rarr; Surat Peringatan (SP).</li><li style=\"margin-bottom:5px\">Pelanggaran berat (butir 1): Pemutusan Hubungan Kerja (PHK) seketika tanpa kompensasi.</li><li style=\"margin-bottom:5px\">3 (tiga) SP aktif dalam 1 (satu) periode kontrak menjadi dasar pengakhiran kontrak.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 9<br>Pengunduran Diri</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">PEGAWAI yang mengundurkan diri wajib memberitahu secara tertulis minimum <strong>30 (tiga puluh) hari</strong> sebelum tanggal efektif.</li><li style=\"margin-bottom:5px\">Pengunduran diri sebelum masa kontrak berakhir tanpa alasan yang dapat diterima dikenakan denda sebesar <strong>Rp 500.000,-</strong>.</li><li style=\"margin-bottom:5px\">PEGAWAI tetap melaksanakan tugas dan kewajibannya penuh hingga batas waktu pengunduran diri berlaku.</li><li style=\"margin-bottom:5px\">PEGAWAI wajib menyelesaikan serah terima tugas dan mengembalikan seluruh inventaris perusahaan dalam kondisi baik.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 10<br>Force Majeure</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Dalam kondisi darurat (bencana alam, pandemi, kebijakan pemerintah) yang menyebabkan operasional terganggu, para pihak bermusyawarah dalam 14 (empat belas) hari untuk mencari solusi bersama.</li><li style=\"margin-bottom:5px\">Pemotongan kompensasi akibat force majeure tidak melebihi <strong>25%</strong> dari kompensasi tetap dan harus atas kesepakatan bersama.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 11<br>Pengakhiran Kontrak</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Kontrak berakhir sendirinya pada tanggal <strong>28 Juni 2026</strong>.</li><li style=\"margin-bottom:5px\">PERUSAHAAN dapat mengakhiri kontrak sebelum waktunya apabila PEGAWAI melakukan pelanggaran berat atau tidak memenuhi standar kinerja minimum setelah evaluasi dan peringatan tertulis.</li><li style=\"margin-bottom:5px\">Berakhirnya PKWT secara alami tidak menimbulkan kewajiban pesangon sesuai PP No. 35 Tahun 2021.</li></ol><p style=\"text-align:center;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;margin:22px 0 6px;letter-spacing:.3px;text-transform:uppercase;text-decoration:underline\">Pasal 12<br>Ketentuan Lain</p><ol style=\"margin:4px 0 10px;padding-left:22px;line-height:1.85\"><li style=\"margin-bottom:5px\">Peraturan Perusahaan dan SOP yang berlaku merupakan satu kesatuan yang tidak terpisahkan dari perjanjian ini.</li><li style=\"margin-bottom:5px\">Perubahan isi perjanjian hanya sah apabila dibuat secara tertulis dan ditandatangani oleh kedua belah pihak.</li><li style=\"margin-bottom:5px\">Hal-hal yang belum diatur dalam perjanjian ini akan diatur kemudian atas kesepakatan para pihak dalam suatu amandemen.</li><li style=\"margin-bottom:5px\">Perjanjian ini tunduk pada hukum yang berlaku di Indonesia, khususnya UU No. 11 Tahun 2020 tentang Cipta Kerja jo. PP No. 35 Tahun 2021.</li><li style=\"margin-bottom:5px\">Perselisihan diselesaikan secara musyawarah. Apabila tidak tercapai, diselesaikan melalui mekanisme ketenagakerjaan yang berlaku.</li></ol></div></div>','',67,'2026-04-03 17:01:21',67,'2026-04-03 17:01:21','2026-08-19 10:08:40'),
(10,'NCE/K1/003/2026',53,1,NULL,'K1','EXPIRED','COOK','KITCHEN',1400000.00,200000.00,0.00,0.00,8000.00,'2026-04-22','2026-07-22','a2f377920368c10ac3e1c5d180caaae2','9c37480558dba4b2320ca5114a59c53d0a61633ea19cc4374d26a7eac10f9e01','2026-04-22 16:23:27','<div style=\"text-align:center;margin-bottom:20px;padding-bottom:14px;border-bottom:2px solid #222\"><img src=\"https://core.namuacoffee.com/assets/img/logo.png\" alt=\"Namua Coffee\" style=\"height:68px;display:block;margin:0 auto 10px\"><div style=\"font-family:Arial,sans-serif;font-size:16px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase\">Namua Coffee and Eatery</div><div style=\"font-family:Arial,sans-serif;font-size:13px;color:#555;margin-top:3px\">Jl. Magnolia, Kabongan Kidul, Kecamatan Rembang</div><div style=\"font-family:Arial,sans-serif;margin-top:12px;font-size:19px;font-weight:bold;text-transform:uppercase;letter-spacing:.6px\">Perjanjian Kerja Waktu Tertentu</div><div style=\"font-family:Arial,sans-serif;font-size:17px;font-weight:bold;margin-top:2px\">Kontrak 1 &mdash; Masa Training (3 bulan)</div></div><div style=\"font-family:\'Times New Roman\',Times,Georgia,serif;font-size:16px;line-height:1.85;color:#1a1a1a\"><p style=\"margin:0 0 8px;text-align:justify;line-height:1.85\">Pada hari ini, 22 April 2026, telah disepakati dan ditandatangani Perjanjian Kerja Waktu Tertentu (PKWT) oleh dan antara:</p><table style=\"width:100%;margin-bottom:14px;border-collapse:collapse;font-family:\'Times New Roman\',Times,Georgia,serif;font-size:16px\"><tr><td style=\"width:28%;padding:5px 10px;border:1px solid #ccc;background:#f5f5f5;font-weight:bold;vertical-align:top\">Pihak Pertama</td><td style=\"padding:5px 10px;border:1px solid #ccc;vertical-align:top\">: <strong>Namua Coffee and Eatery</strong>, diwakili oleh <strong>Anis Fitriya</strong> selaku Owner, berkedudukan di Jl. Magnolia, Desa Kabongan Kidul, Kecamatan Rembang. Selanjutnya disebut <strong>PERUSAHAAN</strong>.</td></tr><tr><td style=\"p